package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.io.File;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbIRI;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbLiteral;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbStatementIteratorValueReuseTest {

	@Test
	void injectedValuesOfCurrentRevisionAreReused(@TempDir File directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig();
		ValueStore values = new ValueStore(new File(directory, "values"), config);
		try (TripleStore triples = new TripleStore(new File(directory, "triples"), config, values)) {
			values.startTransaction(true);
			long[] quad = { values.storeValue(Values.iri("urn:s")), values.storeValue(Values.iri("urn:p")),
					values.storeValue(Values.literal("o")), values.storeValue(Values.iri("urn:c")) };
			values.commit();
			try (TxnManager.ReaderReservation admitted = triples.getTxnManager().reserveReadTxn(false);
					TxnManager.Txn triple = admitted.startPinned(triples::getDataRevision);
					ValueStore.ReadSnapshotReservation reservation = values.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start(triple)) {
				// Non-canonical native instances of the snapshot's revision must be kept as-is.
				LmdbIRI subj = new LmdbIRI(snapshot.revision(), quad[0]);
				LmdbIRI context = new LmdbIRI(snapshot.revision(), quad[3]);
				// A non-native value must be replaced by the store's own native value.
				IRI pred = Values.iri("urn:p");
				// A native value from another revision must be replaced as well.
				LmdbLiteral obj = new LmdbLiteral(new ValueStoreRevision.Default(values), quad[2]);
				try (LmdbStatementIterator iterator = new LmdbStatementIterator(single(quad), values, snapshot, subj,
						pred, obj, context)) {
					Statement statement = iterator.next();
					assertSame(subj, statement.getSubject());
					assertSame(context, statement.getContext());
					assertNotSame(pred, statement.getPredicate());
					assertInstanceOf(LmdbValue.class, statement.getPredicate());
					assertEquals(pred, statement.getPredicate());
					assertNotSame(obj, statement.getObject());
					assertEquals(Values.literal("o"), statement.getObject());
				}
			}
		} finally {
			values.close();
		}
	}

	private static RecordIterator single(long[] quad) {
		return new RecordIterator() {
			private boolean consumed;

			@Override
			public long[] next() {
				if (consumed) {
					return null;
				}
				consumed = true;
				return quad;
			}

			@Override
			public void close() {
			}
		};
	}
}
